const visual = {
  prepare: function (input) {
    var texts = [
      '解一元一次方程 6x + 5 = 2x + 11',
      '流程卡',
      '① 移项',
      '6x − 2x = 11 − 5',
      '② 合并同类项',
      '4x = 6',
      '③ 系数化为 1',
      'x = 6/4 = 3/2'
    ];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var texts = [
      '解一元一次方程 6x + 5 = 2x + 11',
      '流程卡',
      '① 移项',
      '6x − 2x = 11 − 5',
      '② 合并同类项',
      '4x = 6',
      '③ 系数化为 1',
      'x = 6/4 = 3/2'
    ];
    var W = (input.viewport && input.viewport.widthDu) || 900;
    var H = (input.viewport && input.viewport.heightDu) || 440;
    var margin = 40;
    var gap = 50;
    var cardW = (W - margin * 2 - gap * 2) / 3;
    var cardY = 130;
    var cardH = Math.max(200, H - cardY - 80);
    var headerH = 52;
    var cardX = [margin, margin + cardW + gap, margin + (cardW + gap) * 2];
    var centers = [margin + cardW / 2, margin + cardW + gap + cardW / 2, margin + (cardW + gap) * 2 + cardW / 2];
    var headerFills = ['#e8f1ff', '#e6f7f2', '#fff4e2'];
    var headerStrokes = ['#7aa7e8', '#5fc2a3', '#e0a54a'];
    var paths = [];
    var children = [];
    function addPath(id, commands, stroke, fill, strokeWidth) {
      paths.push({ id: id, commands: commands });
      children.push({ type: 'path', pathId: id, stroke: stroke || 'none', fill: fill || 'none', strokeWidth: strokeWidth || 1 });
    }
    function rectCommands(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }
    function lineCommands(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }
    function addLabel(text, x, y, fontSize, fill, weight, anchor) {
      children.push({ type: 'label', text: text, x: x, y: y, fontSize: fontSize, fill: fill, fontWeight: weight || 'normal', textAnchor: anchor || 'middle', dominantBaseline: 'middle' });
    }
    addPath('bg', rectCommands(0, 0, W, H), 'none', '#f6f8fc', 0);
    addLabel(texts[0], W / 2, 46, 22, '#1f2f46', 'bold', 'middle');
    addLabel(texts[1], W / 2, 78, 14, '#6b7b91', 'normal', 'middle');
    for (var i = 0; i < 3; i++) {
      var x = cardX[i];
      addPath('card' + i, rectCommands(x, cardY, cardW, cardH), '#cbd6e4', '#ffffff', 2);
      addPath('head' + i, rectCommands(x, cardY, cardW, headerH), headerStrokes[i], headerFills[i], 1.5);
      addLabel(texts[2 + i * 2], centers[i], cardY + headerH / 2, 18, '#1f2f46', 'bold', 'middle');
      addLabel(texts[3 + i * 2], centers[i], cardY + headerH + 74, 17, '#24364d', 'normal', 'middle');
    }
    var arrowY = cardY + cardH / 2;
    for (var j = 0; j < 2; j++) {
      var x1 = cardX[j] + cardW + 8;
      var x2 = cardX[j + 1] - 8;
      addPath('arrowLine' + j, lineCommands(x1, arrowY, x2, arrowY), '#8a9bb2', 'none', 2);
      addPath('arrowHeadA' + j, lineCommands(x2, arrowY, x2 - 10, arrowY - 6), '#8a9bb2', 'none', 2);
      addPath('arrowHeadB' + j, lineCommands(x2, arrowY, x2 - 10, arrowY + 6), '#8a9bb2', 'none', 2);
    }
    return { schemaVersion: 1, sceneId: 'flowcard-linear-equation', revision: input.revision, viewBox: { x: 0, y: 0, width: W, height: H }, paths: paths, root: { type: 'group', children: children } };
  }
};
